<?php declare(strict_types=1); return static function(PDO $db):void{$db->exec("ALTER TABLE fiches_expression_besoin ADD COLUMN IF NOT EXISTS document_uid VARCHAR(80) NULL AFTER numero_feb");$db->exec("ALTER TABLE fiches_expression_besoin ADD COLUMN IF NOT EXISTS document_version VARCHAR(10) NOT NULL DEFAULT '01' AFTER document_uid");$db->exec("UPDATE fiches_expression_besoin SET document_uid=CONCAT('FID-QMS-FEB-',YEAR(created_at),'-',LPAD(id,6,'0')) WHERE document_uid IS NULL OR document_uid=''");$db->exec("CREATE UNIQUE INDEX IF NOT EXISTS uniq_feb_document_uid ON fiches_expression_besoin(document_uid)");};
